"""Plain arithmetic must be evaluated, not generated by the small model."""
from __future__ import annotations

import pytest

from apps.ai_api.arithmetic import answer_arithmetic_question


@pytest.mark.parametrize("question,expected", [
    ("2+2 bằng mấy?", "2+2 = 4"),
    ("12 * 8 = ?", "12 * 8 = 96"),
    ("10 / 4 bằng bao nhiêu?", "10 / 4 = 2.5"),
    ("3 x 4 bằng mấy", "3*4 = 12"),
    ("Tính 15 + 27", "15 + 27 = 42"),
    ("(8 + 2) * 3 bằng mấy?", "(8 + 2) * 3 = 30"),
    ("What is 7 * 6?", "7 * 6 = 42"),
])
def test_arithmetic_answers(question, expected):
    assert answer_arithmetic_question(question) == expected


def test_division_by_zero_is_explained():
    assert answer_arithmetic_question("5/0 bằng mấy?") == "Không thể chia cho 0."
    assert answer_arithmetic_question("5/0 equals?", language="en") == "Division by zero is undefined."


@pytest.mark.parametrize("question", [
    "20/11 là ngày gì?",
    "2/9 là ngày gì?",
    "Tôi có 2 con mèo",
    "Giải thích continuous integration",
    "2^10 bằng mấy?",
    "2 + 2 = 5 đúng không?",
    "Hãy viết email xin nghỉ phép 1 ngày",
])
def test_non_arithmetic_questions_are_not_hijacked(question):
    assert answer_arithmetic_question(question) is None
